+/// word, so a cache judged without the law reads Stale once.
+pub(super) fn newly_judged(params: &OpParams) -> bool {
+    params.kind().info().section == Section::MultiAxis || matches!(params, OpParams::Drill { cross, .. } if !cross.is_empty())
